// See allEquipmentMods' own comment -- loaded whole, once, filtered/grouped
// client-side. "?lang=<i18next.language>" resolves every real mod's own
// mod_name; a chassis mod's own name is already fully resolved server-side
// too now (see parse_chassis_mod_localized_strings() in
// generate_ships_table.py), so no special client-side handling is needed
// for those despite is_chassis_mod still being present on each row.
async function loadEquipmentMods() {
  const response = await fetch(`/api/equipment_mods?lang=${i18next.language}`);
  allEquipmentMods = await response.json();
}

// See equipmentModTargetMappings' own comment -- a static file, not an API
// endpoint, fetched the same way src/static/i18n/*.json already is.
async function loadEquipmentModTargetMappings() {
  const response = await fetch("/equipment_mod_target_mappings.json");
  equipmentModTargetMappings = await response.json();
}

// Every real (non-chassis) mod whose own mod_components includes
// `modComponentType` (the mod system's own vocabulary -- see
// MOD_LAB_COMPONENT_TYPE_MAP's own comment for how a Component Analyzer
// componentType maps onto it), grouped by mod_level (1/2/3) so the
// Modifications Lab can render one list per tab.
function modsForComponentType(modComponentType) {
  const byLevel = { 1: [], 2: [], 3: [] };
  for (const mod of allEquipmentMods) {
    // Chassis-integrated "mods" (is_chassis_mod) are never offered in the
    // Mod Lab picker at all -- that selection feature was removed (see
    // [[project-mod-modified-stats-architecture]]'s own "lean into real
    // chassis mocking" note): the Chassis Modifier stats now read a
    // ship's own real ships_base column directly via a cross-component
    // mock, so there's nothing left for a chassis-slot pick to do.
    if (mod.is_chassis_mod) continue;
    if (!modComponentType) continue;
    if (!mod.mod_components.split(",").includes(modComponentType)) continue;
    byLevel[mod.mod_level]?.push(mod);
  }
  return byLevel;
}

// ?lang=<i18next.language>, same convention as loadCargoTypeNames() -- see
// api.py's /api/missile_weapon_systems docstring.
async function loadMissileWeaponSystemNames() {
  const response = await fetch(`/api/missile_weapon_systems?lang=${i18next.language}`);
  const weaponSystems = await response.json();
  for (const { weapon_system_id, weapon_system_name } of weaponSystems) {
    missileWeaponSystemNames[weapon_system_id] = weapon_system_name;
  }
}

// A ship's own ships_base.cargo_type is one or two space-separated tokens
// (e.g. "container", "container solid") -- looks each up in
// cargoTypeNames and joins them for display, same convention as
// wareDisplayName's own "fall back to the raw token" spirit. "" (no cargo
// hold at all) returns "" untranslated -- callers gate display on
// summary.cargo_capacity instead of this string being non-empty.
function cargoTypeDisplayName(cargoType) {
  if (!cargoType) return "";
  return cargoType
    .split(" ")
    .map((token) => cargoTypeNames[token] ?? token)
    .join(", ");
}

// Every real compatibility tag on an equipment mount's own connection
// (engines_base/shields_base/weapons_base/turrets_base/thrusters_base/
// missiles_base.compatibility) or a ship's own required compatibility
// class (ship_component_groups.equipment_compatibility_class -- same
// vocabulary, exposed to the frontend as group.compatibility, see
// query_ship_components.py's own docstring) -- both comma-joined (see
// parse_equipment_mount()'s own docstring in generate_ships_table.py for
// why comma here and not cargoTypeDisplayName()'s own space-separated
// shape). Looks each token up in compatibilityTypeNames, same
// token-split-and-lookup/fallback convention as cargoTypeDisplayName().
// "" (no requirement at all) returns "".
function compatibilityDisplayName(compatibility) {
  if (!compatibility) return "";
  return compatibility
    .split(",")
    .map((token) => compatibilityTypeNames[token] ?? token)
    .join(", ");
}

// Same comma-joined token-split-and-lookup/fallback shape as
// compatibilityDisplayName() above, but against ammunitionCompatibilityTypeNames
// -- a distinct vocabulary (missiles_base.compatibility, weapons_base/
// turrets_base.ammunition_tags; see AMMUNITION_TYPE_NAME_REF's own docstring
// in generate_ships_table.py for why these can't share one lookup table).
function ammunitionCompatibilityDisplayName(compatibility) {
  if (!compatibility) return "";
  return compatibility
    .split(",")
    .map((token) => ammunitionCompatibilityTypeNames[token] ?? token)
    .join(", ");
}

// "universal" is thrusters' own synthetic sentinel (THRUSTER_COMPATIBILITY),
// not a real game concept at all, on literally every thruster slot --
// showing it anywhere would be pure noise. The rest are real connection
// tags, but pure geometry/targeting bookkeeping rather than an actual
// equipment restriction -- confirmed by querying every real
// ship_component_groups.equipment_compatibility_class value (excluding
// software groups -- see below) and cross-checking against
// EQUIPMENT_MOUNT_STRUCTURAL_TOKENS in generate_ships_table.py, which
// already excludes "hittable"/"combat" for exactly this reason on the
// equipment side; the ship's own connection tag set is deliberately
// noisier still (query_ship_components.py's own matching_items() only
// requires it be a *superset* of equipment's clean requirement tags, so
// nothing here ever trims it for matching correctness -- this constant
// exists purely so the *display* side doesn't show that extra noise to a
// player). Unlike COMPATIBILITY_BASELINE_TIER_TOKENS below, these are
// never worth showing anywhere, in any context.
const COMPATIBILITY_NOISE_TOKENS = new Set([
  "universal",
  "hittable",
  "unhittable",
  "combat",
  "primary",
  "notupgradeable",
  "component",
  "noshield",
  "platformcollision",
]);

// "standard"/"advanced" are the two ordinary equipment tiers every normal
// mount already implies (see COMPATIBILITY_NAME_REF's own docstring in
// generate_ships_table.py) -- worth excluding from a *per-slot* badge
// (buildGroupRow() -- flagging one of these on literally every ordinary
// slot would be pure clutter) but worth *including* in the ship-wide
// summary line (renderShipSummary() -- a player wants to know at a glance
// whether this hull is a Standard or Advanced build overall).
const COMPATIBILITY_BASELINE_TIER_TOKENS = new Set(["standard", "advanced"]);

// The real, worth-showing tokens on `compatibility` (a group's own
// equipment_compatibility_class, comma-joined) -- always drops pure
// bookkeeping noise (COMPATIBILITY_NOISE_TOKENS, "symmetry*" tokens --
// symmetry_1/2/3/left/right/top/bottom, which side of a mirrored turret
// pair this connection is, filtered by prefix rather than an exhaustive
// set since new ones show up per hull), and additionally drops the two
// baseline tiers unless `includeBaselineTiers` is set. Shared by
// specialCompatibilityDisplayName() (one group's own per-slot badge,
// baseline tiers excluded) and renderShipSummary()'s own ship-wide rollup
// (baseline tiers included, per the user's own request -- "if a ship is
// advanced, it should say advanced"). Callers must skip software-type
// groups entirely before calling this -- a software group's own
// equipment_compatibility_class is repurposed to hold a raw software
// ware_id list, not real compatibility tags at all (see
// generate_ships_table.py's "Software" docstring section), so running it
// through here would just look like a garbled name.
function compatibilityTokens(compatibility, { includeBaselineTiers = false } = {}) {
  if (!compatibility) return [];
  return compatibility.split(",").filter((token) => {
    if (!token || token.startsWith("symmetry")) return false;
    if (COMPATIBILITY_NOISE_TOKENS.has(token)) return false;
    if (!includeBaselineTiers && COMPATIBILITY_BASELINE_TIER_TOKENS.has(token)) return false;
    return true;
  });
}

// Display form of compatibilityTokens() (baseline tiers excluded) for one
// group -- "" when there's nothing special about this particular slot
// worth flagging to the player (see buildGroupRow()'s own comment).
function specialCompatibilityDisplayName(compatibility) {
  const tokens = compatibilityTokens(compatibility);
  if (tokens.length === 0) return "";
  return tokens.map((token) => compatibilityTypeNames[token] ?? token).join(", ");
}

// ?lang=<i18next.language>, same convention as loadFactionNames() -- see
// api.py's /api/wares docstring. Also seeds allWaresCache (see
// openPriceOverrideModal()) so opening the price-override picker never
// needs a second fetch of the exact same data.
async function loadWareNames() {
  const response = await fetch(`/api/wares?lang=${i18next.language}`);
  allWaresCache = await response.json();
  for (const { ware_id, name } of allWaresCache) wareNames[ware_id] = name;
}

// Fills the size/type filter fieldsets with one checkbox per distinct value
// actually present in allShips, sorted, so the filters never offer a choice
// with zero matches. Multiple checkboxes in the same group can be checked
// at once; none checked means "don't filter on that dimension".
// Sizes are stored/filtered on as their raw lowercase abbreviation
// (ship.size, e.g. "s"/"m"/"l"/"xl" -- same value renderShipSummary()
// already .toUpperCase()s for display elsewhere), matching
// sizeValues.includes(ship.size) in shipPassesCurrentFilters(). Factored
// out of populateFilterOptions() (rather than left inline) so the
// Component Analyzer's chassis filter panel (see buildChassisFilterPanel())
// can build the exact same entry list for its own, independently-scoped
// copy of this same filter group.
// `list` defaults to allShips (the main ship picker's own #ship-filters)
// but the Component Analyzer's per-type filter panel (see
// buildComponentTypeFilterPanel()) passes its own currently-fetched
// component list instead -- every entity here just needs a `.size` field,
// ships and engine/shield/weapon/turret/thruster components alike.
function buildSizeFilterEntries(list = allShips) {
  // A null size is real (not a parsing gap): a handful of real equipment
  // wares have no size at all -- e.g. turret_par_m_mining_01_mk1 (GitHub
  // issue #26 phase-5), whose own real mount connection tag in the game's
  // own data genuinely carries no size keyword, and the personal spacesuit
  // engines, which aren't ship-mountable at all. Such a component can
  // never match a real ship slot either way, so it's excluded here rather
  // than crashing the whole picker on `null.toUpperCase()` (a real
  // regression this filter hit the moment that turret got parsed at all).
  return [...new Set(list.map((entity) => entity.size))]
    .filter((size) => size != null)
    .sort((a, b) => SIZE_ORDER.indexOf(a) - SIZE_ORDER.indexOf(b))
    .map((size) => ({ value: size, label: size.toUpperCase() }));
}

// ship.purpose is a flat, single-valued AI role classification (e.g.
// "fight"/"trade"/"mine") -- unlike Type, no ship has more than one, so
// this needs none of buildTypeFilterEntries()'s multi-size splitting.
// Label is purposeNames' own real, localized display name (see
// loadPurposeNames()/api.py's GET /api/purposes) -- falling back to the
// same plain client-side capitalization this used before that existed,
// for any purpose id purposeNames doesn't have an entry for (shouldn't
// happen for a real purpose value, but cheap insurance). Sorted by that
// resolved label, not the raw code, so a non-English list is actually
// alphabetized in that language too -- same reasoning as Vendor's own
// buildVendorFilterEntries(). Factored out for the same reason as
// buildSizeFilterEntries() above.
function buildPurposeFilterEntries() {
  return [...new Set(allShips.map((ship) => ship.purpose))]
    .filter((purpose) => purpose != null)
    .map((purpose) => ({
      value: purpose,
      label: purposeNames[purpose] ?? purpose.charAt(0).toUpperCase() + purpose.slice(1),
    }))
    .sort((a, b) => a.label.localeCompare(b.label));
}

function populateFilterOptions() {
  buildCheckboxGroup(sizeFilterOptions, "size-filter", buildSizeFilterEntries());
  buildCheckboxGroup(purposeFilterOptions, "purpose-filter", buildPurposeFilterEntries());
  buildCheckboxGroup(typeFilterOptions, "type-filter", buildTypeFilterEntries());
  buildCheckboxGroup(vendorFilterOptions, "vendor-filter", buildVendorFilterEntries());
  buildCheckboxGroup(raceFilterOptions, "race-filter", buildRaceFilterEntries());
  buildCheckboxGroup(buildMethodFilterOptions, "build-method-filter", buildBuildMethodFilterEntries());
}

// One checkbox per distinct real race_id appearing in any ship's own
// maker_races (see GET /api/ships' own docstring and
// generate_ships_table.py's "Design race and race/faction shortcodes"
// section) -- the ship's actual design race(s), not a ware_id guess.
// Checkbox `value` is the race_id itself (matching shipPassesCurrentFilters'
// own comparison); the label shown is that race's localized shortname
// (raceInfo, see loadRaceNames()), styled exactly like the picker's own
// .ship-option-race plate (applyRaceTextColor() -- colored text, plus a
// silver/slate backing panel for the harder-to-read colors) via a
// dedicated labelEl span rather than plain text, since color/background
// can't be expressed on a plain text node. Sorted by the displayed
// shortname, not the raw id, so the checkbox order matches what's shown.
// `list` -- see buildSizeFilterEntries()' own comment.
function buildRaceFilterEntries(list = allShips) {
  const raceIds = new Set();
  for (const entity of list) {
    for (const raceId of entity.maker_races ?? []) raceIds.add(raceId);
  }
  return [...raceIds]
    .sort((a, b) => (raceInfo[a]?.shortname ?? a).localeCompare(raceInfo[b]?.shortname ?? b))
    .map((raceId) => {
      const labelEl = document.createElement("span");
      labelEl.className = "filter-option-race-label";
      applyRaceTextColor(labelEl, raceId);
      labelEl.textContent = raceInfo[raceId]?.shortname ?? raceId;
      return { value: raceId, label: raceInfo[raceId]?.shortname ?? raceId, labelEl };
    });
}

// One checkbox per real build-method name actually present among
// allShips' own ship.production_method (ships with no production block at
// all -- a handful of Khaak hulls and drop/terraforming drones -- simply
// contribute nothing, same "never offer a choice with zero matches" rule
// every other filter here follows, e.g. buildRaceFilterEntries()). Filters
// allBuildMethods (see loadBuildMethods()/GET /api/build_methods) down to
// just those, rather than re-deriving the list from allShips directly, so
// the checkbox order matches BUILD_METHODS' own curated order (Universal
// first, Terran second, ...) -- the same order the Cost Analysis Build
// Method modal's own priority list uses -- instead of a plain alphabetical
// sort. Label is colored via applyBuildMethodColor() (see
// BUILD_METHOD_TO_RACE), same "Argon"/"Boron"/etc. race-colored pill
// treatment build method names already get in the Build Method modal and
// the Loadout summary. `value` stays the raw English method name (the real
// matching key -- see shipPassesCurrentFilters()); only the label text is
// resolved through buildMethodNames (see loadBuildMethodNames()).
// `list` -- see buildSizeFilterEntries()' own comment.
function buildBuildMethodFilterEntries(list = allShips) {
  const methodsPresent = new Set(list.map((entity) => entity.production_method).filter((method) => method != null));
  return allBuildMethods
    .filter((method) => methodsPresent.has(method))
    .map((method) => {
      const labelEl = document.createElement("span");
      labelEl.className = "filter-option-race-label";
      applyBuildMethodColor(labelEl, method);
      labelEl.textContent = buildMethodNames[method] ?? method;
      return { value: method, label: buildMethodNames[method] ?? method, labelEl };
    });
}

// One checkbox per real weapon_system value present in `list` (missiles
// only -- see COMPONENT_FILTER_GROUPS), labeled via missileWeaponSystemNames
// (GET /api/missile_weapon_systems, see that endpoint's own docstring in
// api.py) -- real page-1040 "Weapon Systems" text (Dumbfire/Guided/
// Torpedos), not an invented category. Plain text label, no icon/color --
// unlike Race/Build Method, a weapon system has no established color
// convention elsewhere in this app to reuse.
function buildMissileWeaponSystemFilterEntries(list) {
  const weaponSystemIds = new Set(list.map((entity) => entity.weapon_system).filter((value) => value != null));
  return [...weaponSystemIds]
    .map((weaponSystemId) => ({
      value: weaponSystemId,
      label: missileWeaponSystemNames[weaponSystemId] ?? weaponSystemId,
    }))
    .sort((a, b) => a.label.localeCompare(b.label));
}

// One checkbox per real mk (mark/tier) value present in `list` -- engine/
// shield/weapon/turret/thruster only (equipment_wares_base.mk); missiles
// have no mk column at all, so this is never built for that type (see
// COMPONENT_FILTER_GROUPS). Sorted numerically, not alphabetically (mk
// values are small integers, but checkbox `value` attributes are always
// strings -- see checkedValues()/shipPassesCurrentFilters()'s own
// String(ship.mk) comparison).
function buildMkFilterEntries(list) {
  return [...new Set(list.map((entity) => entity.mk).filter((mk) => mk != null))]
    .sort((a, b) => a - b)
    .map((mk) => ({ value: String(mk), label: `Mk${mk}` }));
}

// Economy Wares only (economy_wares_base.transport) -- one checkbox per
// real cargo-hold type present in `list` ("container"/"liquid"/"solid",
// plus real "condensate" outliers -- see economy_wares_base's own schema
// comment). Reuses cargoTypeNames (loaded from GET /api/cargo_types for
// the main ship picker's own Cargo Type stat) for a real display name,
// same fallback-to-raw-value convention as cargoTypeDisplayName() -- a
// "condensate" entry has no cargo_types row, so it just shows raw.
function buildCargoTypeFilterEntries(list) {
  const values = new Set(list.map((ware) => ware.transport).filter((value) => value != null));
  return [...values]
    .map((value) => ({ value, label: cargoTypeNames[value] ?? value }))
    .sort((a, b) => a.label.localeCompare(b.label));
}

// Economy Wares only (economy_wares_base.leaf_ware) -- True/False, not a
// value actually present in the game data the way every other filter
// entry is (see boolStatDef()'s own comment on why leaf_ware is a real
// SQLite BOOLEAN, 0/1 under the hood). Only offers whichever of True/False
// `list` actually contains, same "don't offer a choice with zero matches"
// rule every other filter follows -- sorted True-then-False rather than
// alphabetically, since "False"/"True" would put them in a confusing order.
function buildBaseResourceFilterEntries(list) {
  const values = new Set(list.map((ware) => ware.leaf_ware).filter((value) => value != null));
  return [...values]
    .map((value) => ({
      value: String(value),
      label: value ? t("component_analyzer.true_value") : t("component_analyzer.false_value"),
    }))
    .sort((a, b) => Number(b.value) - Number(a.value));
}

// One checkbox per real faction id appearing in any ship's own
// ships_base.owners (majors and minors alike, e.g. "argon"/"buccaneers"),
// sorted by display name. Icon is the faction's own tinted badge (see
// buildFactionIconImg()/factionIconUrl()) -- "the faction symbol with its
// color" -- while the label text stays plain/unstyled ("just regular
// color"), unlike e.g. .ship-option-race elsewhere which does color its
// own text. Entries with no real icon (shouldn't happen for a genuine
// ships_base.owners value, but factionIconUrl() returning null is a cheap
// defensive check) are silently skipped rather than shown broken.
// `list` -- see buildSizeFilterEntries()' own comment.
function buildVendorFilterEntries(list = allShips) {
  const factionIds = new Set();
  for (const entity of list) {
    for (const ownerFaction of entity.owners ? entity.owners.split(",") : []) factionIds.add(ownerFaction);
  }
  return [...factionIds]
    .filter((factionId) => factionIconUrl(factionId))
    .sort((a, b) => (factionNames[a] ?? a).localeCompare(factionNames[b] ?? b))
    .map((factionId) => ({
      value: factionId,
      label: factionNames[factionId] ?? factionId,
      iconEl: buildFactionIconImg(factionId, "filter-option-faction-icon"),
    }));
}

// `onChange` defaults to renderShipOptions (the main ship picker's own
// filter group) -- the Component Analyzer's chassis filter panel (see
// buildChassisFilterPanel()) passes its own renderComponentSetPickerRows-
// triggering callback instead, since its checkboxes filter a completely
// different list.
function buildCheckboxGroup(container, name, entries, onChange = renderShipOptions) {
  container.innerHTML = "";
  for (const entry of entries) {
    container.appendChild(
      buildCheckboxOption(name, entry.value, entry.label, entry.iconEl ?? null, entry.labelEl ?? null, onChange),
    );
  }
}

// `iconEl` is a pre-built <img> (or null) rather than an icon name string --
// each entries-builder constructs its own kind of icon (buildIconImg() for
// a ship-class icon, e.g. buildTypeFilterEntries(); buildFactionIconImg()
// for a faction badge, e.g. buildVendorFilterEntries()), since which URL
// scheme/class applies depends entirely on which filter group this is, not
// something buildCheckboxOption()/buildCheckboxGroup() themselves need to
// know about. `labelEl`, similarly, is an optional pre-built element used
// in place of a plain text node for the label itself -- e.g.
// buildRaceFilterEntries()'s own colored/plated race-abbreviation span,
// which a plain createTextNode(displayLabel) couldn't render (no styling on
// a text node); `displayLabel` is simply ignored when `labelEl` is given.
function buildCheckboxOption(name, value, displayLabel, iconEl = null, labelEl = null, onChange = renderShipOptions) {
  const label = document.createElement("label");
  const input = document.createElement("input");
  input.type = "checkbox";
  input.name = name;
  input.value = value;
  input.addEventListener("change", onChange);
  label.appendChild(input);
  if (iconEl) label.appendChild(iconEl);
  label.appendChild(labelEl ?? document.createTextNode(displayLabel));
  return label;
}

// `root` scopes the query to one filter panel's own checkboxes -- needed
// once the same filter-group `name`s (see buildChassisFilterPanel()) can
// legitimately appear twice in the document at once (the main ship picker's
// static #ship-filters, and the Component Analyzer's own dynamically-built
// copy inside the "Select Components" modal). Defaults to the whole
// document, matching every pre-existing call site's own behavior.
function checkedValues(name, root = document) {
  return Array.from(root.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);
}

// "All"/"None" buttons are static markup (unlike the checkboxes themselves,
// which are (re)built from the API response), so wiring them up once here
// at load time is enough. Only ever targets the main ship picker's own
// #ship-filters buttons -- the Component Analyzer's own filter panel wires
// its All/None buttons itself (see buildFilterFieldsetForModal()), since
// those don't exist yet when this loop runs.
for (const btn of document.querySelectorAll(".filter-all-btn")) {
  btn.addEventListener("click", () => {
    for (const input of document.querySelectorAll(`input[name="${btn.dataset.filter}"]`)) {
      input.checked = true;
    }
    renderShipOptions();
  });
}

for (const btn of document.querySelectorAll(".filter-none-btn")) {
  btn.addEventListener("click", () => {
    for (const input of document.querySelectorAll(`input[name="${btn.dataset.filter}"]`)) {
      input.checked = false;
    }
    renderShipOptions();
  });
}

// Rebuilds the ship picker listbox from allShips filtered by the current
// size/type checkbox selections (no checkboxes checked in a group means
// "don't filter on that dimension"). Resets the current selection since it
// may no longer be in the filtered set.
//
// Shared with openSelectGameLoadoutModal(), which applies this same
// predicate (plus compareShips' own ordering) to the saved-loadout list
// when opened generically, so "what ships are currently visible in the
// picker" and "what ships' loadouts show up in Select Filter Loadout"
// never drift apart.
// `root` -- see checkedValues()' own docstring -- defaults to the whole
// document (the main ship picker's own #ship-filters), but is passed
// explicitly by the Component Analyzer's chassis filter panel so this same
// predicate can be evaluated against that panel's own, independent
// checkbox selections instead.
function shipPassesCurrentFilters(ship, root = document) {
  const sizeValues = checkedValues("size-filter", root);
  const purposeValues = checkedValues("purpose-filter", root);
  const typeValues = checkedValues("type-filter", root);
  const vendorValues = checkedValues("vendor-filter", root);
  const raceValues = checkedValues("race-filter", root);
  const buildMethodValues = checkedValues("build-method-filter", root);
  // Missile-only (see COMPONENT_FILTER_GROUPS) -- no such checkboxes exist
  // under any other root, so weaponSystemValues is always [] there, making
  // this clause a no-op everywhere except the missile filter panel.
  const weaponSystemValues = checkedValues("weapon-system-filter", root);
  // Equipment-only (see COMPONENT_FILTER_GROUPS) -- no such checkboxes
  // exist under any other root, so mkValues is always [] elsewhere.
  // String(ship.mk), not ship.mk itself: checkbox `value`s are always
  // strings (see buildMkFilterEntries()'s own comment).
  const mkValues = checkedValues("mk-filter", root);
  // Economy Wares-only (see COMPONENT_FILTER_GROUPS) -- no such checkboxes
  // exist under any other root, so these are always [] elsewhere.
  const cargoTypeValues = checkedValues("cargo-type-filter", root);
  const baseResourceValues = checkedValues("base-resource-filter", root);
  const shipOwners = ship.owners ? ship.owners.split(",") : [];
  const shipMakerRaces = ship.maker_races ?? [];
  return (
    (sizeValues.length === 0 || sizeValues.includes(ship.size)) &&
    (purposeValues.length === 0 || purposeValues.includes(ship.purpose)) &&
    (typeValues.length === 0 || typeValues.some((value) => shipMatchesTypeValue(ship, value))) &&
    (vendorValues.length === 0 || vendorValues.some((value) => shipOwners.includes(value))) &&
    (raceValues.length === 0 || raceValues.some((value) => shipMakerRaces.includes(value))) &&
    (buildMethodValues.length === 0 || buildMethodValues.includes(ship.production_method)) &&
    (weaponSystemValues.length === 0 || weaponSystemValues.includes(ship.weapon_system)) &&
    (mkValues.length === 0 || mkValues.includes(String(ship.mk))) &&
    (cargoTypeValues.length === 0 || cargoTypeValues.includes(ship.transport)) &&
    (baseResourceValues.length === 0 || baseResourceValues.includes(String(ship.leaf_ware)))
  );
}

function renderShipOptions() {
  shipOptionsList.innerHTML = "";

  // Explicit arrow wrapper, not a bare shipPassesCurrentFilters reference --
  // Array.prototype.filter's callback gets (element, index, array), and
  // shipPassesCurrentFilters's second parameter is now `root` (see its own
  // docstring), so a bare reference would silently pass the row index as
  // root and break every root.querySelectorAll() call inside it.
  const filtered = allShips.filter((ship) => shipPassesCurrentFilters(ship));

  if (filtered.length === 0) {
    const empty = document.createElement("div");
    empty.className = "ship-options-empty";
    empty.textContent = t("ship_builder.no_ships_match");
    shipOptionsList.appendChild(empty);
  }

  for (const ship of filtered) {
    shipOptionsList.appendChild(buildShipOptionRow(ship));
  }

  selectedShipWareId = "";
  loadShipBtn.disabled = true;
  editingIndex = null;
  setAddToCartBtnLabel(t("ship_builder.add_to_fleet_list"));
  saveState();
}

// One clickable row in the ship picker listbox: its class symbol (see
// shipIconUrl()) plus its own resolved name alone -- size/type used to be
// appended as raw, unlocalized codes (e.g. "(l, destroyer)"); dropped
// because at the time neither had a real localization source, so showing
// them in one language while the name itself was properly localized in
// another was worse than not showing them at all. ship_type now does
// (shipTypeNames, see loadShipTypeNames()/the Type filter's own use of it
// in buildTypeFilterEntries()) but this row was never reverted to add it
// back -- the race badge(s) and Race/Size/Type filters already convey this
// info without cluttering the name line, and that's held up fine since.
// Clicking always starts a fresh "add" -- same
// as the native <select>'s own "change" event used to (see
// applyShipSelection() for the shared part also used by editCartEntry(),
// which must NOT reset editingIndex/addToCartBtn's label -- that's why
// that part is factored out separately rather than done here).
// The "name, with colored design-race abbreviation(s) stacked underneath"
// text column shared by the ship picker's own listbox rows (below) and the
// Component Analyzer's "Select Components" picker table rows (see
// buildComponentPickerRowContent()) -- any entity with a `name` and a real
// `maker_races` list (ships_base/equipment_wares_base both feed this via
// the same maker_races join, see GET /api/ships and GET /api/components'
// own comments) renders identically either place.
function buildEntityIdentityColumn(entity) {
  const textCol = document.createElement("span");
  textCol.className = "ship-option-text";

  const text = document.createElement("span");
  text.className = "ship-option-name";
  text.textContent = entity.name;
  textCol.appendChild(text);

  // One colored abbreviation per real design race in entity.maker_races --
  // usually one, occasionally more (e.g. the Envoy chassis shows both
  // "ARG" and "TEL"), each independently colored via RACE_COLORS/raceInfo.
  // A raceIds container rather than a single span since there can be more
  // than one (see .ship-option-races in style.css for the wrapping/gap).
  const raceIds = entity.maker_races ?? [];
  if (raceIds.length > 0) {
    const racesGroup = document.createElement("span");
    racesGroup.className = "ship-option-races";
    for (const raceId of raceIds) {
      const raceLabel = document.createElement("span");
      raceLabel.className = "ship-option-race";
      applyRaceTextColor(raceLabel, raceId);
      raceLabel.textContent = raceInfo[raceId]?.shortname ?? raceId;
      raceLabel.title = raceInfo[raceId]?.name ?? raceId;
      racesGroup.appendChild(raceLabel);
    }
    textCol.appendChild(racesGroup);
  }

  return textCol;
}

// Right-aligned (via .ship-option-faction-icons' own margin-left: auto)
// group of full-size owner-faction badges -- one per entry in
// entity.owners (comma-joined, e.g. "argon,buccaneers,hatikvah,scaleplate"
// -- ships_base.owners and equipment_wares_base.owners share this exact
// shape, see generate_ships_table.py's parse_ship_wares()/
// parse_equipment_wares()). No separate manufacturer/design-race badge
// here -- that's already shown as the colored race abbreviation(s) from
// buildEntityIdentityColumn(), so showing it a second time as an icon
// would be redundant. Returns an empty (no-children) group when there are
// no real owners to show -- callers check .children.length before
// appending, same as buildShipOptionRow() always did.
function buildEntityOwnerIconsGroup(entity) {
  const factionIconsGroup = document.createElement("span");
  factionIconsGroup.className = "ship-option-faction-icons";
  for (const ownerFaction of entity.owners ? entity.owners.split(",") : []) {
    if (factionIconUrl(ownerFaction)) {
      factionIconsGroup.appendChild(buildFactionIconImg(ownerFaction, "ship-option-owner-icon"));
    }
  }
  return factionIconsGroup;
}

function buildShipOptionRow(ship) {
  const row = document.createElement("div");
  row.className = "ship-option-row";
  row.dataset.wareId = ship.ware_id;
  row.setAttribute("role", "option");

  if (ship.icon) row.appendChild(buildIconImg(ship.icon, "ship-icon"));
  row.appendChild(buildEntityIdentityColumn(ship));

  const factionIconsGroup = buildEntityOwnerIconsGroup(ship);
  if (factionIconsGroup.children.length > 0) row.appendChild(factionIconsGroup);

  row.addEventListener("click", () => {
    applyShipSelection(ship.ware_id);
    editingIndex = null;
    setAddToCartBtnLabel(t("ship_builder.add_to_fleet_list"));
  });

  return row;
}

// Highlights `wareId`'s row (if present in the currently rendered list) and
// enables/disables the Load button accordingly -- the part of "selecting a
// ship" shared between a user's click (buildShipOptionRow(), which also
// resets editingIndex) and editCartEntry()'s programmatic restore (which
// must not, since it's what sets editingIndex in the first place).
function applyShipSelection(wareId) {
  selectedShipWareId = wareId;
  for (const row of shipOptionsList.querySelectorAll(".ship-option-row")) {
    row.classList.toggle("selected", row.dataset.wareId === wareId);
  }
  loadShipBtn.disabled = !wareId;
}

loadShipBtn.addEventListener("click", async () => {
  const identifier = selectedShipWareId;
  if (!identifier) return;
  const response = await fetch(`/api/ships/${encodeURIComponent(identifier)}/groups?lang=${i18next.language}`);
  const data = await response.json();
  if (data.error) {
    alert(t("ship_builder.could_not_load_ship", { error: data.error }));
    return;
  }
  currentShip = data;
  missileAmounts = {}; // a freshly (re)loaded ship always starts with no ammo/countermeasures/drones/deployables/crew picked
  countermeasureAmounts = {};
  droneAmounts = {};
  deployableAmounts = {};
  crewAmounts = {};
  resetShipModLabSlots();
  importedLoadoutWarningsEl.classList.add("hidden");
  renderShipDetail(data);
});

// This app's own invented UI category labels (not game data -- see
// i18n.js) -- functions rather than plain lookup objects so every call
// site always reflects the current language via t(), same reasoning as
// cartDisplayLabel()/wareCostListCategoryLabel() below.
function componentTypeLabel(componentType) {
  return t(`component_type.${componentType}`);
}
const COMPONENT_TYPE_ORDER = ["engine", "thruster", "weapon", "missile_launcher", "shield", "turret", "software"];

// Singular form of componentTypeLabel(), for the equipment picker
// button/modal title ("Select Weapon", not "Select Weapons") -- a
// separate key set rather than stripping a trailing "s" since "Software"
// has none to strip.
function componentTypeSingularLabel(componentType) {
  return t(`component_type_singular.${componentType}`, { defaultValue: t("equipment_picker_modal.fallback_equipment") });
}

// Grouping for the Fleet List's own "Loadout" display (see
// renderCart()) -- a superset of componentTypeLabel()/COMPONENT_TYPE_ORDER
// above (which only covers ship_component_groups' component_type values) plus "chassis"
// (the ship hull itself) and the three shared-pool categories that never
// go through a group at all (missile/drone/deployable). "main_shield"/
// "surface_element_shield" split out of the generic "shield"
// component_type (see shieldDisplayCategory() below) the same way
// summarize_production.py's group_by_component_type option already splits
// them for the Ware Cost List, rather than lumping every shield together.
// Anything tagged with a category not listed here (shouldn't normally
// happen) falls back to the raw category code itself (see cart_display.*'s
// defaultValue below), mirroring the Ware Cost List's own "production_wares"
// catch-all.
//
// crew_marine/crew_service are deliberately NOT part of the cart_display.*
// i18next keys below -- unlike every other entry here (this app's own
// invented UI category labels), "Marines"/"Service crew" are real game
// text (see crewRoleNames/loadCrewRoleNames(), CREW_ROLE_NAME_REF in
// generate_ships_table.py) with their own already-localized source; a
// second, separately-authored translation here would drift from it.
function cartDisplayLabel(category) {
  if (category === "crew_marine") return crewRoleNames.marine ?? category;
  if (category === "crew_service") return crewRoleNames.service ?? category;
  return t(`cart_display.${category}`, { defaultValue: category });
}
// Matches the ship builder's own on-screen section order exactly (see
// renderShipDetail()/COMPONENT_TYPE_ORDER for the equipment groups, then
// renderAmmunitionSection/renderDroneSection/renderDeployableSection/
// renderCountermeasureSection/renderCrewSection for the shared-pool
// sections after them, in that call order) -- "chassis" prepended (the
// ship itself, picked before any of its equipment) and "production_wares"
// appended (the catch-all "other" bucket, not a real builder section at
// all). Reused as-is by the Ware Cost List's own category ordering (see
// sortCategoriesForDisplay()) so both places agree.
const CART_DISPLAY_ORDER = [
  "chassis",
  "engine",
  "thruster",
  "weapon",
  "missile_launcher",
  "main_shield",
  "surface_element_shield",
  "turret",
  "software",
  "missile",
  "drone",
  "deployable",
  "countermeasure",
  "crew_marine",
  "crew_service",
  "production_wares",
];
const CART_DISPLAY_FALLBACK_CATEGORY = "production_wares";

// Splits the generic "shield" component_type into "main_shield" vs
// "surface_element_shield" for cartDisplayLabel()/CART_DISPLAY_ORDER -- any other
// component_type passes through unchanged. Shared by addToCartBtn's
// handler (which knows a row is a bonus shield from its own
// "bonus-shield-row" class) and reconstructCartEntry() (which instead
// reads it back off the wares_list item's own "category" override, set
// when it was originally added -- see waresListItem.category below).
function shieldDisplayCategory(componentType, isSurfaceElementShield) {
  if (componentType !== "shield") return componentType;
  return isSurfaceElementShield ? "surface_element_shield" : "main_shield";
}

// group_name alone is NOT unique within data.groups -- a dedicated medium
// shield protecting a specific engine/turret/weapon group shares that
// group's own raw group_name from the game's XML, distinguished only by
// component_type ("shield" vs whatever the sibling is). See
// query_ship_groups()'s docstring in query_ship_components.py. This key is
// what actually identifies one picker uniquely, so it's used for DOM
// dataset identity and for the cart's `selections` map instead of raw
// group_name.
function groupKey(group) {
  return `${group.group_name}::${group.component_type}`;
}

// UI-only requirement: these groups must have a selection before a ship
// can be added to the fleet list. Not enforced anywhere server-side
// (the API will happily calculate a cart missing them) -- purely a picker
// safeguard against forgetting an engine/thruster/core-software choice
// before committing a ship. Engine/thruster are matched by component_type
// (their group_name is always exactly that literal string anyway); software
// slots are matched by group_name, since component_type "software" alone
// doesn't distinguish which category.
function requiredGroupLabel(group) {
  if (group.component_type === "engine") return t("component_type_singular.engine");
  if (group.component_type === "thruster") return t("component_type_singular.thruster");
  const key = `required_software.${group.group_name}`;
  return i18next.exists(key) ? t(key) : null;
}

// Which of a ship's recommended groups (per requiredGroupLabel() above)
// have no selection in `selections` -- shared by addToCartBtn's handler
// (which instead reads this straight off the DOM's own
// .group-row[data-required-label] rows, an equivalent but DOM-driven
// computation) and reconstructCartEntry() (which has no DOM to query at
// all, only the raw groups/selections data from a saved file).
function missingRequiredLabels(groups, selections) {
  const missing = [];
  for (const group of groups) {
    const label = requiredGroupLabel(group);
    if (label && !selections[groupKey(group)]) missing.push(label);
  }
  return missing;
}

// Builds one .group-row (label + picker <select>) for a single group. Used
// for both ordinary groups and bonus-M-shield groups -- the latter get a
// friendlier label (their group_name is shared with the group they
// protect, not meant for display on its own) but are otherwise a
// completely ordinary, independently pickable group: same dataset
// attributes, same .group-select class, so all the existing cart-building/
// edit-repopulating code (which just queries every ".group-row" under
// #groups-container) picks them up automatically with no special-casing.
function buildGroupRow(group, { isLinkedShield = false, sectionType } = {}) {
  const row = document.createElement("div");
  row.className = "group-row";
  row.dataset.groupKey = groupKey(group);
  row.dataset.groupName = group.group_name;
  row.dataset.slotCount = group.slot_count;
  // Read back in addToCartBtn's handler to group the fleet list's
  // own display by component type (see CART_DISPLAY_GROUP_LABELS/
  // renderCart()) -- bonus-M-shield rows are still plain "shield" here
  // (isLinkedShield only changes the *label* above), so they group
  // together with ordinary main shields, same as this app's own picker
  // sections already treat them as one "Shields" category.
  row.dataset.componentType = group.component_type;
  // Which *rendered section* (COMPONENT_TYPE_ORDER entry) this row's card
  // lives under -- not always the same as component_type above, since a
  // linked bonus shield's own component_type is "shield" but it's
  // rendered nested inside its parent's section (e.g. "engine"). Used by
  // applyHighPreset()/applyMinimumPreset() to scope a section's preset
  // buttons to exactly the rows visually inside that section.
  if (sectionType) row.dataset.sectionType = sectionType;

  const label = document.createElement("label");
  const labelText = isLinkedShield
    ? t("ship_builder.bonus_m_shield_label", { count: group.slot_count })
    : `${group.group_name} (${group.component_type}, ${group.size}, x${group.slot_count})`;
  label.textContent = labelText;

  const requiredLabel = requiredGroupLabel(group);
  if (requiredLabel) {
    row.dataset.requiredLabel = requiredLabel;
    const marker = document.createElement("span");
    marker.className = "required-marker";
    marker.textContent = " *";
    marker.title = t("ship_builder.recommended_tooltip");
    label.appendChild(marker);
  }

  // Only shown when this slot needs something beyond the two ordinary
  // equipment tiers (e.g. "Mining", "High-Energy", a race lock) -- see
  // specialCompatibilityDisplayName()'s own comment on why plain
  // standard/advanced/bookkeeping tags never render one, to avoid flagging
  // the vast majority of perfectly ordinary slots. Software groups are
  // skipped entirely -- their own compatibility field is a ware_id list,
  // not real compatibility tags (see specialCompatibilityTokens()'s own
  // comment).
  const specialCompat =
    group.component_type === "software" ? "" : specialCompatibilityDisplayName(group.compatibility);
  if (specialCompat) {
    const compatBadge = document.createElement("span");
    compatBadge.className = "group-row-compatibility-badge";
    compatBadge.textContent = specialCompat;
    compatBadge.title = t("component_analyzer.stat_labels.compatibility");
    label.appendChild(compatBadge);
  }
  row.appendChild(label);

  // A bonus shield's own mod -- user call: right next to its "Bonus M
  // Shield" name (a row sibling right after `label`, not nested inside
  // it -- `label` is inline by default and only 220px wide, no room for a
  // 40px circle without wrapping weirdly; `row` itself is the flex
  // container buildModLabButton()'s own margin-left: auto expects), not
  // trailing the row like turret/weapon below, since there's no single
  // wider row it could trail (each bonus shield is its own independent
  // group). A MAIN shield (not isLinkedShield) gets no row-level button
  // at all -- it's covered by the Shields section's own combined one
  // instead (see renderShipDetail()'s own heading-row button).
  if (isLinkedShield) {
    const modBtn = buildShipModLabButton(`bonus_shield::${group.group_name}`, "shield", null, labelText);
    modBtn.classList.add("component-analyzer-mod-lab-btn-row", "group-row-bonus-shield-mod-btn");
    row.appendChild(modBtn);
  }

  const select = document.createElement("select");
  select.className = "group-select";
  const noneOption = document.createElement("option");
  noneOption.value = "";
  noneOption.textContent = t("equipment_picker_modal.clear_option_row");
  select.appendChild(noneOption);
  for (const option of group.options) {
    const opt = document.createElement("option");
    opt.value = option.ware_id;
    opt.textContent = option.name;
    // <option> can't render partial-colored text (no nested markup
    // support), so the whole option is tinted in its race's color when
    // its name carries a recognized race prefix -- see raceColorForName().
    const raceColor = raceColorForName(option.name);
    if (raceColor) opt.style.color = raceColor;
    // Only set for missile-capable turrets/weapons (null for everything
    // else) -- read back by updateSelectedAmmoCapacity() on every
    // .group-select change to keep the summary panel's running total live.
    if (option.ammunition_capacity != null) {
      opt.dataset.ammoCapacity = option.ammunition_capacity;
    }
    // Comma-joined set of missile compatibility tags this specific
    // launcher accepts (e.g. "dumbfire,mediumdumbfire") -- read back by
    // compatibleMissiles() to decide which missiles the Ammunition section
    // offers, given whatever's currently selected across every launcher.
    if (option.ammunition_tags) {
      opt.dataset.ammoTags = option.ammunition_tags;
    }
    select.appendChild(opt);
  }
  if (group.options.length === 0) {
    select.disabled = true;
    noneOption.textContent = t("equipment_picker_modal.no_compatible_equipment");
  }
  // The <select> stays in the DOM (just hidden) rather than being removed
  // -- every existing piece of cart-building/edit-restore/ammo-capacity
  // logic reads or sets its .value/.options and listens for its "change"
  // event, none of which needs to change now that a button+modal (below)
  // is the actual visible/interactive control. See openEquipmentPickerModal().
  select.classList.add("hidden");
  row.appendChild(select);

  const pickerBtn = document.createElement("button");
  pickerBtn.type = "button";
  pickerBtn.className = "group-select-btn";
  pickerBtn.disabled = group.options.length === 0;
  pickerBtn.addEventListener("click", () => openEquipmentPickerModal(row, group));
  row.appendChild(pickerBtn);
  syncGroupSelectButtonLabel(row);

  // A turret or weapon/missile launcher group's own mod -- one per group
  // (user call), trailing the row same as Component Analyzer's own
  // per-row Mod Lab launcher (reuses that exact convention, including
  // leaving margin-left: auto alone so it pushes itself to the row's far
  // end). Both weapon AND missile_launcher use the "weapon" mod category
  // -- there's no separate missile-launcher mod in-game either, same
  // SHIP_GROUP_TYPE_TO_MOCK_TYPE reasoning that already folds the launcher
  // itself into "weapon" for stat-formula purposes.
  if (group.component_type === "turret") {
    const modBtn = buildShipModLabButton(`turret::${group.group_name}`, "turret", null, labelText);
    modBtn.classList.add("component-analyzer-mod-lab-btn-row");
    row.appendChild(modBtn);
  } else if (group.component_type === "weapon" || group.component_type === "missile_launcher") {
    const modBtn = buildShipModLabButton(`weapon::${group.group_name}`, "weapon", null, labelText);
    modBtn.classList.add("component-analyzer-mod-lab-btn-row");
    row.appendChild(modBtn);
  }

  return row;
}

// Sets a .group-row's visible picker button to reflect its (hidden)
// .group-select's current value -- called right after building the row
// (nothing selected yet) and anywhere else the select's value changes
// programmatically rather than through the modal's own row click (see
// applyGroupSelections(), the edit-restore path). Not needed after an
// ordinary modal selection -- selectEquipmentPickerOption() calls it
// directly there.
function syncGroupSelectButtonLabel(row) {
  const select = row.querySelector(".group-select");
  const btn = row.querySelector(".group-select-btn");
  if (!select || !btn) return;

  if (!select.value) {
    btn.textContent = select.options[0].textContent; // "-- none --" or "-- no compatible equipment found --"
    btn.classList.add("group-select-btn-empty");
    return;
  }
  btn.classList.remove("group-select-btn-empty");
  const selectedOption = select.options[select.selectedIndex];
  btn.textContent = "";
  appendNameWithRaceColor(btn, selectedOption.textContent);
}

// The .group-row/group data currently open in the equipment picker modal,
// or null -- selectEquipmentPickerOption()/the Clear button need to know
// which row's <select> to update (and, for the "apply to all matching
// slots" checkbox, which group's siblings to consider), and
// closeEquipmentPickerModal() clears both so a stray call after the
// modal's closed is a no-op.
let equipmentPickerModalRow = null;
let equipmentPickerModalGroup = null;

// True when `group` is a dedicated bonus/surface-element shield -- a
// group_name shared with a non-shield sibling group on the same ship
// (see parse_component_slots' docstring in generate_ships_table.py) --
// as opposed to an ordinary standalone main shield slot. Mirrors the
// isLinkedShield distinction buildGroupRow()/renderShipDetail() already
// draw from the DOM structure, recomputed here from raw group data since
// the picker modal only has `currentShip.groups` to work with, not the
// rendered card layout.
function isLinkedShieldGroup(group, allGroups) {
  if (group.component_type !== "shield") return false;
  return allGroups.some((g) => g.group_name === group.group_name && g.component_type !== "shield");
}

// Every *other* group on the ship that the "apply to all matching slots"
// checkbox should also try to update alongside `group` -- same
// component_type and size, and (for shields specifically) the same
// bonus-vs-main status, so a main shield selection never bleeds into a
// bonus M shield slot or vice versa. Deliberately does NOT check whether
// a given ware_id is actually valid for each sibling here -- same-type/
// same-size slots on one ship aren't guaranteed to share the same option
// pool (e.g. a hull-locked "mandatory" mount alongside ordinary ones, or
// a mining ship's mixed-tag turret groups both size M) -- that check
// happens per-sibling in selectEquipmentPickerOption() instead, right
// before applying.
function siblingGroupsForBulkApply(group, allGroups) {
  const groupIsLinkedShield = isLinkedShieldGroup(group, allGroups);
  return allGroups.filter((other) => {
    if (other === group) return false;
    if (other.component_type !== group.component_type || other.size !== group.size) return false;
    if (group.component_type === "shield" && isLinkedShieldGroup(other, allGroups) !== groupIsLinkedShield) return false;
    return true;
  });
}

// Opens the equipment picker modal for one .group-row: fetches each
// option's own level-1 production inputs (POST /api/level1_parts, one
// summarize() call per option server-side -- see that endpoint's own
// docstring for why a single combined call wouldn't work here, each row
// needs its *own* inputs, not a total across every option) and renders a
// table with Name/Min/Avg/Max Price plus one dynamic column per distinct
// input ware across every option in this group. A group with no options
// at all never gets here -- its button is disabled (see buildGroupRow()).
async function openEquipmentPickerModal(row, group) {
  equipmentPickerModalRow = row;
  equipmentPickerModalGroup = group;
  equipmentPickerApplyAllCheckbox.checked = false;
  equipmentPickerModalTitle.textContent = t("equipment_picker_modal.select_type_title", {
    type: componentTypeSingularLabel(group.component_type),
  });
  equipmentPickerThead.innerHTML = "";
  equipmentPickerTbody.innerHTML = "";
  equipmentPickerModalStatus.textContent = t("equipment_picker_modal.loading_level1_wares");
  equipmentPickerModalStatus.classList.remove("hidden");
  equipmentPickerModalOverlay.classList.remove("hidden");

  // Level-1 wares are an enhancement on top of the name/price columns,
  // not something selection depends on -- if the request fails, still
  // render the table (just without those extra columns) rather than
  // leaving the picker unusable.
  let partsData = { parts: {}, part_names: {} };
  try {
    const response = await fetch("/api/level1_parts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ware_ids: group.options.map((option) => option.ware_id), lang: i18next.language }),
    });
    if (response.ok) partsData = await response.json();
  } catch {
    // fall through with the empty default above
  }

  // The row's own selection could have changed (or the modal could have
  // been closed) while the fetch above was in flight -- only render if
  // this call is still the one the user is looking at.
  if (equipmentPickerModalRow !== row) return;
  equipmentPickerModalStatus.classList.add("hidden");
  renderEquipmentPickerTable(row, group, partsData);
}

function renderEquipmentPickerTable(row, group, partsData) {
  const select = row.querySelector(".group-select");
  const parts = partsData.parts ?? {};
  const partNames = partsData.part_names ?? {};

  // Union of every distinct level-1 input ware across all of this group's
  // options -- each option's own row only fills in the columns that
  // actually apply to it (see the per-row loop below), left blank
  // otherwise. Sorted by display name so column order doesn't depend on
  // dict/object key order.
  const partIds = new Set();
  for (const option of group.options) {
    for (const partId of Object.keys(parts[option.ware_id] ?? {})) partIds.add(partId);
  }
  const sortedPartIds = [...partIds].sort((a, b) => (partNames[a] ?? a).localeCompare(partNames[b] ?? b));

  equipmentPickerThead.innerHTML = "";
  const headRow = document.createElement("tr");
  const fixedHeaders = [
    t("equipment_picker_modal.table_name_header"),
    t("equipment_picker_modal.table_min_header"),
    t("equipment_picker_modal.table_avg_header"),
    t("equipment_picker_modal.table_max_header"),
  ];
  for (const label of [...fixedHeaders, ...sortedPartIds.map((id) => partNames[id] ?? id)]) {
    const th = document.createElement("th");
    th.textContent = label;
    headRow.appendChild(th);
  }
  equipmentPickerThead.appendChild(headRow);

  equipmentPickerTbody.innerHTML = "";

  const clearRow = document.createElement("tr");
  clearRow.className = "equipment-picker-row equipment-picker-clear-row";
  const clearTd = document.createElement("td");
  clearTd.textContent = t("equipment_picker_modal.clear_option_row");
  clearTd.colSpan = 4 + sortedPartIds.length;
  clearRow.appendChild(clearTd);
  clearRow.addEventListener("click", () => selectEquipmentPickerOption(""));
  equipmentPickerTbody.appendChild(clearRow);

  for (const option of group.options) {
    const tr = document.createElement("tr");
    tr.className = "equipment-picker-row";
    if (select.value === option.ware_id) tr.classList.add("selected");

    const nameTd = document.createElement("td");
    appendNameWithRaceColor(nameTd, option.name);
    tr.appendChild(nameTd);

    for (const priceField of ["price_min", "price_avg", "price_max"]) {
      const td = document.createElement("td");
      td.textContent = option[priceField] != null ? option[priceField] : "-";
      tr.appendChild(td);
    }

    const optionParts = parts[option.ware_id] ?? {};
    for (const partId of sortedPartIds) {
      const td = document.createElement("td");
      td.textContent = optionParts[partId] != null ? optionParts[partId] : "";
      tr.appendChild(td);
    }

    tr.addEventListener("click", () => selectEquipmentPickerOption(option.ware_id));
    equipmentPickerTbody.appendChild(tr);
  }
}

// Applies a modal row click (or the Clear button, via wareId "") to a
// single .group-row's real <select> -- dispatching "change" rather than
// just setting .value so the existing delegated listener (ammo capacity/
// Ammunition section) fires exactly as it would for a direct user
// selection, then syncs the visible button label.
function applySelectionToRow(row, wareId) {
  const select = row.querySelector(".group-select");
  select.value = wareId;
  select.dispatchEvent(new Event("change", { bubbles: true }));
  syncGroupSelectButtonLabel(row);
}

// Applies a modal row click (or the Clear button, via wareId "") to the
// open group, and -- when the "apply to all matching slots" checkbox is
// checked -- to every sibling slot too (same component_type/size, same
// bonus-vs-main status for shields; see siblingGroupsForBulkApply()).
// Clearing (wareId "") always applies to every sibling, since "-- none --"
// is trivially valid everywhere; a real selection only applies to a
// sibling whose own options actually include it -- confirmed by hand
// against the game data that same-type/same-size slots on one ship don't
// always share the same option pool (e.g. the Teladi Miner's front vs.
// back M turret groups, or a hull-locked weapon mount alongside ordinary
// ones), so this must check per-sibling rather than assume uniformity.
// A sibling this ware isn't valid for is left completely untouched
// (whatever it already had selected, or nothing), not cleared.
function selectEquipmentPickerOption(wareId) {
  if (!equipmentPickerModalRow || !equipmentPickerModalGroup) return;
  applySelectionToRow(equipmentPickerModalRow, wareId);

  if (equipmentPickerApplyAllCheckbox.checked && currentShip) {
    const siblings = siblingGroupsForBulkApply(equipmentPickerModalGroup, currentShip.groups);
    for (const sibling of siblings) {
      if (wareId !== "" && !sibling.options.some((option) => option.ware_id === wareId)) continue;
      const siblingRow = [...groupsContainer.querySelectorAll(".group-row")].find(
        (candidate) => candidate.dataset.groupKey === groupKey(sibling),
      );
      if (siblingRow) applySelectionToRow(siblingRow, wareId);
    }
  }

  closeEquipmentPickerModal();
}

function closeEquipmentPickerModal() {
  equipmentPickerModalGroup = null;
  equipmentPickerModalOverlay.classList.add("hidden");
  equipmentPickerModalRow = null;
}

equipmentPickerClearBtn.addEventListener("click", () => selectEquipmentPickerOption(""));
equipmentPickerCancelBtn.addEventListener("click", closeEquipmentPickerModal);

// GET /api/wares result, cached after the first successful fetch -- every
// ware in the database is a fixed, session-static list (nothing here
// changes while the app is running), so there's no reason to re-fetch it
// on every "Set Ware Price Overrides" click.
let allWaresCache = null;

// ware_id -> override price (a plain number). In-memory only (page refresh
// loses it), but real: sent as computeWareCostList()'s price_overrides on
// every calculation, where api.py substitutes it for that ware's price_min/
// price_avg/price_max alike, across all three Ware Cost List tiers. Still
// missing a compact always-visible list of active overrides once the modal
// is closed -- see TODO.md's "Ware price override tool" entry.
const priceOverrides = {};

async function openPriceOverrideModal() {
  priceOverrideModalOverlay.classList.remove("hidden");
  priceOverrideTbody.innerHTML = "";
  priceOverrideSearchInput.value = "";
  priceOverrideHighlightedRow = null;

  if (allWaresCache) {
    renderPriceOverrideTable(allWaresCache);
    return;
  }

  priceOverrideModalStatus.textContent = t("price_override_modal.loading_wares");
  priceOverrideModalStatus.classList.remove("hidden");
  try {
    await loadWareNames(); // seeds allWaresCache too -- see its own docstring
  } catch {
    priceOverrideModalStatus.textContent = t("price_override_modal.failed_to_load_wares");
    return;
  }
  priceOverrideModalStatus.classList.add("hidden");
  renderPriceOverrideTable(allWaresCache);
}

// Every ware_id appearing anywhere in a fleet list itself (not the
// computed cost breakdown) -- across every fleet in `fleets`, not just the
// active one. Each entry contributes its own ship plus everything in its
// wares_list (equipment, ammo, drones, ...). Backs the "Fleet list wares"
// filter checkbox.
function cartWareIds() {
  const ids = new Set();
  for (const fleet of fleets) {
    for (const entry of fleet.cart) {
      ids.add(entry.shipWareId);
      for (const item of entry.wares_list) ids.add(item.ware_id);
    }
  }
  return ids;
}

// ware_ids from one summarize()-shaped result's flat "parts"
// ({"build_method_priority": [...], "parts": {ware_id: amount}, ...}) --
// a null result (e.g. a fleet with no wareCostList yet) or one whose
// build_method_priority resolved to nothing (no "parts" key at all) just
// contributes nothing.
function wareIdsFromSummarizeResult(result) {
  const ids = new Set();
  if (!result) return ids;
  for (const wareId of Object.keys(result.parts ?? {})) ids.add(wareId);
  return ids;
}

// Every ware_id currently shown in the Ware Cost List's Production Wares
// (tierKey "production_wares") or Raw Materials (tierKey "raw_materials")
// tier -- across every fleet's own column in the table, not just the active
// one. Reads .total (the flat, ungrouped tier) rather than .component_type,
// since which wares appear is identical either way -- component_type only
// changes how they're bucketed for display, not the underlying set.
function wareIdsInWareCostListTier(tierKey) {
  const ids = new Set();
  for (const fleet of fleets) {
    if (!fleet.wareCostList) continue;
    for (const id of wareIdsFromSummarizeResult(fleet.wareCostList.total[tierKey])) ids.add(id);
  }
  return ids;
}

// Unchecked is no filter at all (show everything). Any combination of
// checked boxes is a union, not an intersection -- a ware shows up if it
// matches *any* checked filter. "Production wares"/"Raw resources" match
// the actual per-ware breakdown currently rendered in those Ware Cost
// List tiers (not a static database property); "Fleet list wares"
// matches cart membership instead, an entirely different axis (the
// fleet lists themselves, not their computed cost breakdown) that
// can freely combine with either of the other two.
function filterPriceOverrideWares(wares) {
  const productionChecked = priceOverrideFilterProductionCheckbox.checked;
  const rawChecked = priceOverrideFilterRawCheckbox.checked;
  const procurementChecked = priceOverrideFilterProcurementCheckbox.checked;
  if (!productionChecked && !rawChecked && !procurementChecked) return [...wares];

  const productionIds = productionChecked ? wareIdsInWareCostListTier("production_wares") : null;
  const rawIds = rawChecked ? wareIdsInWareCostListTier("raw_materials") : null;
  const cartIds = procurementChecked ? cartWareIds() : null;

  return wares.filter((ware) => {
    if (productionChecked && productionIds.has(ware.ware_id)) return true;
    if (rawChecked && rawIds.has(ware.ware_id)) return true;
    if (procurementChecked && cartIds.has(ware.ware_id)) return true;
    return false;
  });
}

function renderPriceOverrideTable(wares) {
  priceOverrideTbody.innerHTML = "";
  priceOverrideHighlightedRow = null;
  const sorted = filterPriceOverrideWares(wares).sort((a, b) => (a.name ?? a.ware_id).localeCompare(b.name ?? b.ware_id));

  for (const ware of sorted) {
    const tr = document.createElement("tr");

    // Lowercased once at render time -- handlePriceOverrideSearch() runs
    // on every keystroke, so it just reads this back rather than
    // re-deriving/re-lowercasing the display name on every search.
    tr.dataset.searchName = (ware.name ?? ware.ware_id).toLowerCase();

    const nameTd = document.createElement("td");
    nameTd.textContent = ware.name ?? ware.ware_id;
    tr.appendChild(nameTd);

    for (const priceField of ["price_min", "price_avg", "price_max"]) {
      const td = document.createElement("td");
      td.textContent = ware[priceField] == null ? "—" : formatPriceValue(ware[priceField]);
      tr.appendChild(td);
    }

    const overrideTd = document.createElement("td");
    const overrideInput = document.createElement("input");
    overrideInput.type = "number";
    overrideInput.min = "0";
    overrideInput.step = "any";
    overrideInput.placeholder = "no override";
    overrideInput.className = "price-override-input";
    if (priceOverrides[ware.ware_id] !== undefined) overrideInput.value = priceOverrides[ware.ware_id];
    overrideInput.addEventListener("input", () => {
      if (overrideInput.value === "") {
        delete priceOverrides[ware.ware_id];
      } else {
        priceOverrides[ware.ware_id] = Number(overrideInput.value);
      }
      renderPriceOverrideSummary();
    });
    overrideTd.appendChild(overrideInput);
    tr.appendChild(overrideTd);

    priceOverrideTbody.appendChild(tr);
  }
}

// Ware name for display, falling back to the raw ware_id when
// allWaresCache hasn't been loaded yet (e.g. the summary box renders once
// on page load, before "Set Ware Price Overrides" has ever been opened --
// moot in practice since there can't be any overrides set yet either, but
// keeps this function total rather than assuming the cache exists).
function wareDisplayName(wareId) {
  return allWaresCache?.find((ware) => ware.ware_id === wareId)?.name ?? wareId;
}

// Keeps the "Configured Ware Price Overrides" box (next to the Ware Cost
// List title) in sync with the priceOverrides map -- called on every
// override edit (see the input listener above) and whenever the picker
// modal closes, so it's accurate whether or not that modal has ever been
// opened this session.
function renderPriceOverrideSummary() {
  priceOverrideSummaryList.innerHTML = "";
  const entries = Object.entries(priceOverrides);

  if (entries.length === 0) {
    const empty = document.createElement("span");
    empty.className = "price-override-summary-empty";
    empty.textContent = t("ware_cost_list.overrides_none");
    priceOverrideSummaryList.appendChild(empty);
    return;
  }

  entries.sort((a, b) => wareDisplayName(a[0]).localeCompare(wareDisplayName(b[0])));
  for (const [wareId, price] of entries) {
    const row = document.createElement("div");
    row.className = "price-override-summary-entry";

    const name = document.createElement("span");
    name.className = "price-override-summary-name";
    name.textContent = wareDisplayName(wareId);
    row.appendChild(name);

    const value = document.createElement("span");
    value.className = "price-override-summary-value";
    value.textContent = formatPriceValue(price);
    row.appendChild(value);

    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "price-override-summary-remove-btn";
    removeBtn.textContent = "×";
    removeBtn.title = t("price_override_modal.remove_override_tooltip", { name: wareDisplayName(wareId) });
    // Deletes straight from priceOverrides -- doesn't need to touch the
    // modal's own table (it re-derives each input's value fresh from
    // priceOverrides every time it's opened, see renderPriceOverrideTable()),
    // so this works whether or not that modal has ever been opened.
    removeBtn.addEventListener("click", () => {
      delete priceOverrides[wareId];
      renderPriceOverrideSummary();
      markAllFleetsDirtyAndRecompute();
    });
    row.appendChild(removeBtn);

    priceOverrideSummaryList.appendChild(row);
  }
}

// Overrides only take effect on the next computeWareCostList() call, and
// affect every fleet's cost (price_overrides is sent with every
// /api/price_summary request regardless of which fleet's wares are being
// priced) -- so a changed override makes every fleet's cached wareCostList
// stale at once, not just the active one. Recomputed immediately here
// (rather than deferred to the next Cost Analysis visit) since this can
// only be reached from *within* the Cost Analysis page in the first place --
// "navigate in" will never fire again while already there.
function markAllFleetsDirtyAndRecompute() {
  for (const fleet of fleets) fleet.dirty = true;
  recomputeDirtyFleets();
}

function closePriceOverrideModal() {
  priceOverrideModalOverlay.classList.add("hidden");
  renderPriceOverrideSummary();
  markAllFleetsDirtyAndRecompute();
}

// The row scrolled to/highlighted by the last search, if any -- cleared
// (and its highlight removed) at the start of every new search so at most
// one row is ever marked, and reset whenever the modal reopens/re-renders
// since a fresh render's rows are entirely new elements.
let priceOverrideHighlightedRow = null;

// Live "jump to" search, run on every keystroke: highlights and scrolls to
// the first row (in the table's current, name-sorted order) whose name
// contains the typed text so far, case-insensitively. Substring match
// rather than prefix-only, so e.g. typing "shield" still finds "M Shield
// Generator" partway through a name. An empty search box just clears any
// existing highlight without picking a new match.
function handlePriceOverrideSearch() {
  if (priceOverrideHighlightedRow) {
    priceOverrideHighlightedRow.classList.remove("price-override-row-highlight");
    priceOverrideHighlightedRow = null;
  }

  const query = priceOverrideSearchInput.value.trim().toLowerCase();
  if (!query) return;

  const match = [...priceOverrideTbody.querySelectorAll("tr")].find((row) => row.dataset.searchName.includes(query));
  if (!match) return;

  match.classList.add("price-override-row-highlight");
  priceOverrideHighlightedRow = match;
  match.scrollIntoView({ block: "center", behavior: "smooth" });
}
priceOverrideSearchInput.addEventListener("input", handlePriceOverrideSearch);

for (const checkbox of [priceOverrideFilterProductionCheckbox, priceOverrideFilterRawCheckbox, priceOverrideFilterProcurementCheckbox]) {
  checkbox.addEventListener("change", () => renderPriceOverrideTable(allWaresCache ?? []));
}

priceOverrideBtn.addEventListener("click", openPriceOverrideModal);
priceOverrideCloseBtn.addEventListener("click", closePriceOverrideModal);

// Which labeled section a group_name's bundle belongs to: the non-shield
// component_type when there is one (so an engine's dedicated bonus shield
// still lands in "Engines", not a separate "Shields" section -- matching
// how it's already rendered nested under that same card), else "shield"
// for a standalone main-shield-only group_name (e.g. shield_1/2/3).
function bundleSectionType(entries) {
  const nonShield = entries.find((g) => g.component_type !== "shield");
  return nonShield ? nonShield.component_type : "shield";
}

// A pencil-edit field for the loadout's own name (shipNoteInput's value --
// the same "Loadout Name" the bottom-of-page input already edits, and
// what "Add To Saved Loadouts"/the Trial Builder's own "Add to Trial"
// both save under) shown right under the ship's own name, so it's visible
// without scrolling past the whole groups/ammo/drone/etc. section first.
// Deliberately NOT built on top of buildEditableNameField()'s own default
// rerender (renderComponentAnalyzerTables) -- that'd have to be
// renderShipDetail() here instead, which rebuilds #groups-container from
// the chassis's own default options, silently discarding any component
// swap the user hasn't saved yet (selections only ever live in the live
// <select> elements, see captureCurrentGroupSelections()'s own comment).
// This re-renders only itself.
function renderShipLoadoutNameField() {
  shipLoadoutNameRow.innerHTML = "";
  const wrap = document.createElement("span");
  wrap.className = "ship-loadout-name-field";

  const showDisplay = () => {
    wrap.replaceChildren();
    const editBtn = document.createElement("button");
    editBtn.type = "button";
    editBtn.className = "editable-name-edit-btn";
    editBtn.textContent = "✎";
    editBtn.title = t("component_analyzer.rename_tooltip");
    editBtn.addEventListener("click", showInput);

    const nameText = document.createElement("span");
    nameText.className = "editable-name-text";
    nameText.textContent = shipNoteInput.value.trim() || t("ship_builder.loadout_name_placeholder");

    wrap.append(editBtn, nameText);
  };

  const showInput = () => {
    wrap.replaceChildren();
    const input = document.createElement("input");
    input.type = "text";
    input.className = "editable-name-input";
    input.placeholder = t("ship_builder.loadout_name_placeholder");
    input.value = shipNoteInput.value;

    const commit = () => {
      shipNoteInput.value = input.value;
      showDisplay();
    };
    input.addEventListener("blur", commit);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        input.blur();
      } else if (event.key === "Escape") {
        input.removeEventListener("blur", commit);
        showDisplay();
      }
    });

    wrap.appendChild(input);
    input.focus();
    input.select();
  };

  showDisplay();
  shipLoadoutNameRow.appendChild(wrap);
}

function renderShipDetail(data) {
  shipDetail.classList.remove("hidden");
  shipNameEl.innerHTML = "";
  if (data.icon) shipNameEl.appendChild(buildIconImg(data.icon, "ship-icon ship-name-icon"));
  shipNameEl.appendChild(document.createTextNode(data.name));
  updatePlayerLocationMarker(data.icon);
  selectChassisLoadoutBtn.textContent = t("ship_builder.select_named_loadout", { name: data.name });
  updateSelectChassisLoadoutBtnState();
  addToSavedLoadoutsStatus.classList.add("hidden");
  renderShipSummary(data);
  renderShipLoadoutNameField();

  groupsContainer.innerHTML = "";

  // "Chassis Mod" -- the one ship-wide mod that isn't tied to any
  // equipped group at all (a real hull/chassis mod in-game), so it's its
  // own row above every section rather than living in one of their
  // heading rows -- user call: top right, above the Engines section,
  // labeled "Chassis Mod" next to the button.
  const chassisModRow = document.createElement("div");
  chassisModRow.className = "ship-chassis-mod-row";
  const chassisModLabel = document.createElement("span");
  chassisModLabel.className = "ship-chassis-mod-label";
  chassisModLabel.textContent = t("ship_builder.chassis_mod_label");
  chassisModRow.appendChild(chassisModLabel);
  chassisModRow.appendChild(buildShipModLabButton("chassis", "chassis", data.ware_id, data.name));
  groupsContainer.appendChild(chassisModRow);

  // Group every entry by its (possibly shared) group_name first. A
  // group_name used by more than one component_type means one of them is a
  // dedicated shield protecting the other(s) -- rendered nested inside the
  // same card, right below the protected group's own picker, so the
  // association is visually unambiguous. A group_name used only by
  // shield(s) (e.g. shield_1/2/3) is a normal, standalone main shield slot
  // and renders as an ordinary top-level row.
  const entriesByGroupName = new Map();
  for (const group of data.groups) {
    if (!entriesByGroupName.has(group.group_name)) entriesByGroupName.set(group.group_name, []);
    entriesByGroupName.get(group.group_name).push(group);
  }

  // Bundle each group_name's cards, then bucket those bundles into
  // labeled sections by component type (COMPONENT_TYPE_ORDER/LABELS,
  // already used for the summary panel, doubles as the section list here
  // so both stay in sync). A ship missing a whole category (e.g. no
  // turrets) just doesn't get that section at all.
  const bundlesBySection = new Map();
  for (const entries of entriesByGroupName.values()) {
    const sectionType = bundleSectionType(entries);
    if (!bundlesBySection.has(sectionType)) bundlesBySection.set(sectionType, []);
    bundlesBySection.get(sectionType).push(entries);
  }

  for (const sectionType of COMPONENT_TYPE_ORDER) {
    const bundles = bundlesBySection.get(sectionType);
    if (!bundles) continue;

    const section = document.createElement("div");
    section.className = "picker-section";

    const headingRow = document.createElement("div");
    headingRow.className = "picker-section-heading-row";
    const heading = document.createElement("h4");
    heading.className = "picker-section-title";
    heading.textContent = componentTypeLabel(sectionType);
    headingRow.appendChild(heading);

    const highBtn = document.createElement("button");
    highBtn.type = "button";
    highBtn.className = "section-preset-btn";
    highBtn.textContent = t("ship_builder.high_preset");
    highBtn.title = t("ship_builder.high_preset_tooltip");
    highBtn.addEventListener("click", () => applyHighPreset(sectionType));
    headingRow.appendChild(highBtn);

    const minBtn = document.createElement("button");
    minBtn.type = "button";
    minBtn.className = "section-preset-btn";
    minBtn.textContent = t("ship_builder.minimum_preset");
    minBtn.title = t("ship_builder.minimum_preset_tooltip");
    minBtn.addEventListener("click", () => applyMinimumPreset(sectionType));
    headingRow.appendChild(minBtn);

    // One combined mod for the whole section -- user call: back on the
    // right (trailing the High/Minimum Preset buttons), with every OTHER
    // section reserving the same blank space via an invisible placeholder
    // so every section's own High/Minimum Preset pair still lines up at
    // the same x position either way. Engines (section "engine",
    // COMPONENT_TYPE_ORDER's first entry) covers BOTH the engine and
    // thruster groups together (there's no separate thruster mod category
    // in-game either, see MOD_LAB_COMPONENT_TYPE_MAP's own engine/thruster
    // -> "engine" mapping), and Shields covers every MAIN shield slot
    // together -- a BONUS shield nested under another section gets its
    // own separate mod instead (see buildGroupRow()'s own isLinkedShield
    // branch below), so this never renders for the Shields section's own
    // nested bonus-shield rows, only the section heading itself.
    if (sectionType === "engine") {
      headingRow.appendChild(buildShipModLabButton("engine", "engine", null, componentTypeLabel("engine")));
    } else if (sectionType === "shield") {
      headingRow.appendChild(buildShipModLabButton("shield", "shield", null, componentTypeLabel("shield")));
    } else {
      // No section-wide mod button here (Thrusters/Weapons/Missile
      // Launchers/Turrets/Software) -- an invisible same-size placeholder
      // still reserves its exact spot.
      const modBtnSpacer = document.createElement("span");
      modBtnSpacer.className = "ship-mod-lab-btn-spacer";
      headingRow.appendChild(modBtnSpacer);
    }

    section.appendChild(headingRow);

    for (const entries of bundles) {
      const card = document.createElement("div");
      card.className = "group-card";

      const nonShield = entries.filter((g) => g.component_type !== "shield");
      const shields = entries.filter((g) => g.component_type === "shield");
      const isLinked = nonShield.length > 0; // else: a standalone shield-only group_name

      for (const group of nonShield) {
        card.appendChild(buildGroupRow(group, { sectionType }));
      }
      for (const group of shields) {
        const row = buildGroupRow(group, { isLinkedShield: isLinked, sectionType });
        if (isLinked) row.classList.add("bonus-shield-row");
        card.appendChild(row);
      }

      section.appendChild(card);
    }

    groupsContainer.appendChild(section);
  }

  updateSelectedAmmoCapacity();
  renderAmmoInfoBox();
  renderAmmunitionSection();
  renderDroneSection();
  renderDeployableSection();
  renderCountermeasureSection();
  renderCrewSection();
}

// The chassis's own base `baseKey` column (missile_capacity/drone_capacity/
// deployable_capacity/countermeasure_capacity), live-adjusted for a
// currently-applied Chassis Mod via that same stat's own *_post_mod
// formula (missile_capacity_post_mod/etc. -- CHASSIS_STAT_DEFINITIONS,
// same modifierModStatDef()/postModStatDef() pattern every other
// moddable stat already uses) -- see refreshShipModLabButtons()'s own
// comment for when this needs re-reading. Falls back to the real chassis
// row's own base value if the Post Mod formula can't resolve for any
// reason (componentListCache not warm yet, etc.) -- never worse than the
// pre-mod-aware behavior this replaces.
function shipLiveCapacity(baseKey, postModKey) {
  if (!currentShip) return 0;
  const chassisRow = statSourceForComponentType("chassis").get(currentShip.ware_id);
  if (!chassisRow) return currentShip.summary[baseKey] ?? 0;
  const def = lookupStatDef("chassis", postModKey);
  if (!def) return chassisRow[baseKey] ?? 0;
  const value = resolveStatValue(def, chassisRow, {
    componentType: "chassis",
    table: null,
    component: shipModLabSlots.chassis?.component ?? null,
    resolving: new Set(),
  });
  return typeof value === "number" ? value : (chassisRow[baseKey] ?? 0);
}

// Total missile capacity = the ship's own live (mod-adjusted, see
// shipLiveCapacity()) missile_capacity (an independent contribution --
// not derived from any launcher, see ships_base.missile_capacity) PLUS
// ammunition_capacity (per-unit, from a missile-capable turret's/
// weapon's own selected option -- see query_ship_components.py's
// matching_items() docstring) summed across every currently-selected
// group, scaled by that group's own slot_count (a group with slot_count
// 2 mounts two of whatever's selected, so it contributes double the
// capacity). Entirely client-side, no API call needed since every
// option's ammunition_capacity and the ship's own missile_capacity
// already arrived with the initial GET /api/ships/{id}/groups response.
function totalMissileCapacity() {
  if (!currentShip) return 0;

  let total = shipLiveCapacity("missile_capacity", "missile_capacity_post_mod");
  for (const row of groupsContainer.querySelectorAll(".group-row")) {
    const select = row.querySelector(".group-select");
    const selectedOption = select.options[select.selectedIndex];
    if (selectedOption && selectedOption.dataset.ammoCapacity !== undefined) {
      total += Number(selectedOption.dataset.ammoCapacity) * Number(row.dataset.slotCount);
    }
  }
  return total;
}

// Re-run on every .group-select change (delegated listener below) and
// once right after the picker (re)renders, so it's always in sync with
// whatever's actually selected.
function updateSelectedAmmoCapacity() {
  const line = document.getElementById("selected-ammo-capacity-line");
  if (line) line.textContent = t("ship_builder.total_missile_capacity", { count: totalMissileCapacity() });
}

function totalSelectedMissiles() {
  return Object.values(missileAmounts).reduce((sum, amount) => sum + amount, 0);
}

// The union of every currently-selected launcher's own ammunition_tags
// (see buildGroupRow()) -- a missile is offered in the Ammunition section
// when its own single compatibility tag is a member of this set.
function acceptedAmmunitionTags() {
  const tags = new Set();
  for (const row of groupsContainer.querySelectorAll(".group-row")) {
    const select = row.querySelector(".group-select");
    const selectedOption = select.options[select.selectedIndex];
    if (selectedOption && selectedOption.dataset.ammoTags) {
      for (const tag of selectedOption.dataset.ammoTags.split(",")) tags.add(tag);
    }
  }
  return tags;
}

function compatibleMissiles() {
  const accepted = acceptedAmmunitionTags();
  return allMissiles.filter((missile) => missile.compatibility && accepted.has(missile.compatibility));
}

// One row: missile name + a qty stepper (+/-, and a directly-typeable
// number input), mirroring the cart's own quantity control. Mutates
// missileAmounts directly and re-derives the running total/comparison on
// every change -- never rebuilds the whole Ammunition section on a qty
// edit (only a launcher swap does that, since only that can change which
// missiles are even compatible).
function buildAmmoRow(missile) {
  const row = document.createElement("div");
  row.className = "ammo-row";

  const label = document.createElement("label");
  label.textContent = missile.name;
  row.appendChild(label);

  const qtyWrap = document.createElement("span");
  qtyWrap.className = "qty-control";

  const qtyInput = document.createElement("input");
  qtyInput.type = "number";
  qtyInput.min = "0";
  qtyInput.className = "qty-input";
  qtyInput.value = missileAmounts[missile.ware_id] ?? 0;

  // Capped at how much room is left in the shared missile-capacity pool --
  // this row's own current amount plus whatever capacity every other row
  // hasn't already claimed -- so typed values, +/- clicks, and shift+plus's
  // "fill remaining" (see plusBtn below) can never push the total over
  // totalMissileCapacity() through this row.
  const setAmount = (value) => {
    const otherTotal = totalSelectedMissiles() - (missileAmounts[missile.ware_id] ?? 0);
    const maxAllowed = Math.max(0, totalMissileCapacity() - otherTotal);
    const amount = Math.min(maxAllowed, Math.max(0, Math.floor(Number(value)) || 0));
    if (amount === 0) {
      delete missileAmounts[missile.ware_id];
    } else {
      missileAmounts[missile.ware_id] = amount;
    }
    qtyInput.value = amount;
    updateAmmoSummary();
  };

  qtyInput.addEventListener("change", () => setAmount(qtyInput.value));

  const minusBtn = document.createElement("button");
  minusBtn.type = "button";
  minusBtn.textContent = "-";
  minusBtn.className = "qty-btn";
  // Shift+click zeroes this row out in one step; ctrl+click steps by 10
  // instead of 1 (still 1 if this row has less than 10 left to give up).
  minusBtn.addEventListener("click", (event) =>
    setAmount(event.shiftKey ? 0 : Number(qtyInput.value) - (event.ctrlKey ? 10 : 1)),
  );

  const plusBtn = document.createElement("button");
  plusBtn.type = "button";
  plusBtn.textContent = "+";
  plusBtn.className = "qty-btn";
  // Shift+click fills this row up to whatever's left in the shared pool --
  // setAmount's own capping above does the actual clamping, Infinity just
  // asks it for "as much as possible". Ctrl+click (without shift) steps by
  // 10 instead of 1.
  plusBtn.addEventListener("click", (event) =>
    setAmount(event.shiftKey ? Infinity : Number(qtyInput.value) + (event.ctrlKey ? 10 : 1)),
  );

  qtyWrap.appendChild(minusBtn);
  qtyWrap.appendChild(qtyInput);
  qtyWrap.appendChild(plusBtn);
  row.appendChild(qtyWrap);

  return row;
}

// Shown above the Ammunition section whenever a ship is loaded, regardless
// of whether that ship actually has any ammunition to show (the counter
// shortcuts apply to every qty counter in the ship builder, not just
// ammunition rows) -- kept in its own container, separate from
// ammunitionContainer, so renderAmmunitionSection()'s early-return for
// "no compatible missiles" can't make it disappear along with the section
// it happens to sit above. Populated once per ship load from
// renderShipDetail(); cleared alongside everything else in
// resetShipPicker().
function renderAmmoInfoBox() {
  ammoInfoBoxContainer.innerHTML = "";

  const box = document.createElement("div");
  box.className = "info-box";
  const icon = document.createElement("span");
  icon.className = "info-box-icon";
  icon.textContent = "i";
  box.appendChild(icon);
  const text = document.createElement("span");
  text.textContent = t("ship_builder.counter_hint");
  box.appendChild(text);

  ammoInfoBoxContainer.appendChild(box);
}

// Rebuilds the Ammunition section from scratch: which missiles are
// compatible can change on every launcher swap, so this re-derives that
// set (dropping any missileAmounts entry that's no longer compatible --
// its count is simply lost, matching "only compatible missiles are
// offered") and rebuilds the row list. The whole section is omitted
// entirely (not even a heading) when nothing is compatible yet, rather
// than showing an empty placeholder. Called after every ship
// (re)render/edit-repopulation and on every .group-select change.
function renderAmmunitionSection() {
  ammunitionContainer.innerHTML = "";
  if (!currentShip) return;

  const missiles = compatibleMissiles();
  const compatibleIds = new Set(missiles.map((missile) => missile.ware_id));
  for (const wareId of Object.keys(missileAmounts)) {
    if (!compatibleIds.has(wareId)) delete missileAmounts[wareId];
  }

  if (missiles.length === 0) return;

  const section = document.createElement("div");
  section.className = "picker-section";

  const heading = document.createElement("h4");
  heading.className = "picker-section-title";
  heading.textContent = t("ship_builder.ammunition_section_title");
  section.appendChild(heading);

  const card = document.createElement("div");
  card.className = "group-card";
  for (const missile of missiles) {
    card.appendChild(buildAmmoRow(missile));
  }
  section.appendChild(card);

  const summaryLine = document.createElement("div");
  summaryLine.id = "ammo-summary-line";
  summaryLine.className = "ammo-summary-line";
  section.appendChild(summaryLine);

  ammunitionContainer.appendChild(section);
  updateAmmoSummary();
}

function updateAmmoSummary() {
  const line = document.getElementById("ammo-summary-line");
  if (!line) return;

  const total = totalSelectedMissiles();
  const capacity = totalMissileCapacity();
  line.textContent = t("ship_builder.total_missiles", { total, capacity });
  line.classList.toggle("over-capacity", total > capacity);
}

function totalSelectedDrones() {
  return Object.values(droneAmounts).reduce((sum, amount) => sum + amount, 0);
}

// Unlike missile capacity, this is purely the ship's own live (mod-
// adjusted, see shipLiveCapacity()) drone_capacity (ships_base.drone_capacity,
// e.g. builders ~100-250, carriers ~20) -- no per-launcher contribution
// to add, since drones aren't tied to any equipped weapon/turret the way
// missiles are.
function totalDroneCapacity() {
  return shipLiveCapacity("drone_capacity", "drone_capacity_post_mod");
}

// One row: drone name + a qty stepper, same control as buildAmmoRow().
function buildDroneRow(drone) {
  const row = document.createElement("div");
  row.className = "ammo-row";

  const label = document.createElement("label");
  label.textContent = drone.name;
  row.appendChild(label);

  const qtyWrap = document.createElement("span");
  qtyWrap.className = "qty-control";

  const qtyInput = document.createElement("input");
  qtyInput.type = "number";
  qtyInput.min = "0";
  qtyInput.className = "qty-input";
  qtyInput.value = droneAmounts[drone.ware_id] ?? 0;

  // Capped at how much room is left in the shared drone-capacity pool --
  // see buildAmmoRow()'s setAmount for the full explanation.
  const setAmount = (value) => {
    const otherTotal = totalSelectedDrones() - (droneAmounts[drone.ware_id] ?? 0);
    const maxAllowed = Math.max(0, totalDroneCapacity() - otherTotal);
    const amount = Math.min(maxAllowed, Math.max(0, Math.floor(Number(value)) || 0));
    if (amount === 0) {
      delete droneAmounts[drone.ware_id];
    } else {
      droneAmounts[drone.ware_id] = amount;
    }
    qtyInput.value = amount;
    updateDroneSummary();
  };

  qtyInput.addEventListener("change", () => setAmount(qtyInput.value));

  const minusBtn = document.createElement("button");
  minusBtn.type = "button";
  minusBtn.textContent = "-";
  minusBtn.className = "qty-btn";
  // Shift+click zeroes this row out in one step; ctrl+click steps by 10
  // instead of 1 (still 1 if this row has less than 10 left to give up).
  minusBtn.addEventListener("click", (event) =>
    setAmount(event.shiftKey ? 0 : Number(qtyInput.value) - (event.ctrlKey ? 10 : 1)),
  );

  const plusBtn = document.createElement("button");
  plusBtn.type = "button";
  plusBtn.textContent = "+";
  plusBtn.className = "qty-btn";
  // Shift+click fills this row up to whatever's left in the shared pool;
  // ctrl+click (without shift) steps by 10 instead of 1.
  plusBtn.addEventListener("click", (event) =>
    setAmount(event.shiftKey ? Infinity : Number(qtyInput.value) + (event.ctrlKey ? 10 : 1)),
  );

  qtyWrap.appendChild(minusBtn);
  qtyWrap.appendChild(qtyInput);
  qtyWrap.appendChild(plusBtn);
  row.appendChild(qtyWrap);

  return row;
}

// Rebuilds the Drones section. Unlike renderAmmunitionSection(), which
// group is compatible never depends on anything else selected in the
// picker (no per-launcher concept for drones), so this is only called
// once per ship (re)render/edit-repopulation -- never on a .group-select
// change. The whole section is omitted entirely (not even a heading) when
// this ship has no drone capacity at all, rather than showing an empty
// placeholder.
function renderDroneSection() {
  droneContainer.innerHTML = "";
  if (!currentShip) return;

  const capacity = totalDroneCapacity();
  if (capacity <= 0) {
    droneAmounts = {};
    return;
  }

  const section = document.createElement("div");
  section.className = "picker-section";

  const heading = document.createElement("h4");
  heading.className = "picker-section-title";
  heading.textContent = t("ship_builder.drones_section_title");
  section.appendChild(heading);

  const card = document.createElement("div");
  card.className = "group-card";
  for (const drone of allDrones) {
    card.appendChild(buildDroneRow(drone));
  }
  section.appendChild(card);

  const summaryLine = document.createElement("div");
  summaryLine.id = "drone-summary-line";
  summaryLine.className = "ammo-summary-line";
  section.appendChild(summaryLine);

  droneContainer.appendChild(section);
  updateDroneSummary();
}

function updateDroneSummary() {
  const line = document.getElementById("drone-summary-line");
  if (!line) return;

  const total = totalSelectedDrones();
  const capacity = totalDroneCapacity();
  line.textContent = t("ship_builder.total_drones", { total, capacity });
  line.classList.toggle("over-capacity", total > capacity);
}

function totalSelectedDeployables() {
  return Object.values(deployableAmounts).reduce((sum, amount) => sum + amount, 0);
}

// The game data has no per-ship BASE deployable capacity stat at all
// (unlike missile_capacity/drone_capacity) -- ships_base.deployable_capacity
// is itself just an assumed default keyed by the ship's own size
// (DEPLOYABLE_CAPACITY_BY_SIZE in generate_ships_table.py), computed
// server-side. A real mod CAN still raise it from there though (see
// shipLiveCapacity()), same as the other 3.
function totalDeployableCapacity() {
  return shipLiveCapacity("deployable_capacity", "deployable_capacity_post_mod");
}

// One row: deployable name + a qty stepper, same control as buildAmmoRow()/buildDroneRow().
function buildDeployableRow(deployable) {
  const row = document.createElement("div");
  row.className = "ammo-row";

  const label = document.createElement("label");
  label.textContent = deployable.name;
  row.appendChild(label);

  const qtyWrap = document.createElement("span");
  qtyWrap.className = "qty-control";

  const qtyInput = document.createElement("input");
  qtyInput.type = "number";
  qtyInput.min = "0";
  qtyInput.className = "qty-input";
  qtyInput.value = deployableAmounts[deployable.ware_id] ?? 0;

  // Capped at how much room is left in the shared deployable-capacity pool
  // -- see buildAmmoRow()'s setAmount for the full explanation.
  const setAmount = (value) => {
    const otherTotal = totalSelectedDeployables() - (deployableAmounts[deployable.ware_id] ?? 0);
    const maxAllowed = Math.max(0, totalDeployableCapacity() - otherTotal);
    const amount = Math.min(maxAllowed, Math.max(0, Math.floor(Number(value)) || 0));
    if (amount === 0) {
      delete deployableAmounts[deployable.ware_id];
    } else {
      deployableAmounts[deployable.ware_id] = amount;
    }
    qtyInput.value = amount;
    updateDeployableSummary();
  };

  qtyInput.addEventListener("change", () => setAmount(qtyInput.value));

  const minusBtn = document.createElement("button");
  minusBtn.type = "button";
  minusBtn.textContent = "-";
  minusBtn.className = "qty-btn";
  // Shift+click zeroes this row out in one step; ctrl+click steps by 10
  // instead of 1 (still 1 if this row has less than 10 left to give up).
  minusBtn.addEventListener("click", (event) =>
    setAmount(event.shiftKey ? 0 : Number(qtyInput.value) - (event.ctrlKey ? 10 : 1)),
  );

  const plusBtn = document.createElement("button");
  plusBtn.type = "button";
  plusBtn.textContent = "+";
  plusBtn.className = "qty-btn";
  // Shift+click fills this row up to whatever's left in the shared pool;
  // ctrl+click (without shift) steps by 10 instead of 1.
  plusBtn.addEventListener("click", (event) =>
    setAmount(event.shiftKey ? Infinity : Number(qtyInput.value) + (event.ctrlKey ? 10 : 1)),
  );

  qtyWrap.appendChild(minusBtn);
  qtyWrap.appendChild(qtyInput);
  qtyWrap.appendChild(plusBtn);
  row.appendChild(qtyWrap);

  return row;
}

// Rebuilds the Deployables section -- same shape as renderDroneSection()
// (no per-selection compatibility, only called once per ship (re)render/
